import java.util.Scanner;

public class Main {
    static final int MAXN = 577;
    static int n, m, Mod;
    static long[] dp = new long[MAXN];
    static long[] dp2 = new long[MAXN];
    static long[][] C = new long[MAXN][MAXN];
    static long[][] res = new long[MAXN][MAXN];
    static long[][] res2 = new long[MAXN][MAXN];

    static long sumRange(int left, int right) {
        long sum = ((long)(left + right) * (right - left + 1)) / 2;
        return sum % Mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        Mod = sc.nextInt();

        for (int i = 0; i < MAXN; ++i) {
            C[i][0] = 1;
            C[i][i] = 1;
        }
        for (int i = 1; i < MAXN; ++i) {
            for (int j = 1; j < i; ++j) {
                C[j][i] = (C[j][i - 1] + C[j - 1][i - 1]) % Mod;
            }
        }

        dp[0] = 1;
        dp2[0] = 0;

        for (int length = 1; length <= n; ++length) {
            for (int i = 1; i <= length; ++i) {
                int total = (int)(sumRange(1, i - 1) + sumRange(1, length - i)) % Mod;
                int count = length + 1;

                long temp1 = ((dp[i - 1] * count) % Mod * dp[length - i]) % Mod * C[i - 1][length - 1] % Mod;
                long temp2 = ((long)total * dp[i - 1]) % Mod * dp[length - i] % Mod * C[i - 1][length - 1] % Mod;
                long temp3 = ((long)dp2[i - 1] * count) % Mod * dp[length - i] % Mod * C[i - 1][length - 1] % Mod;
                long temp4 = ((long)dp2[length - i] * count) % Mod * dp[i - 1] % Mod * C[i - 1][length - 1] % Mod;

                dp[length] = (dp[length] + temp1) % Mod;
                dp2[length] = (dp2[length] + temp2 + temp3 + temp4) % Mod;
            }
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= m && j <= i; ++j) {
                res[i][j] = res[i - 1][j];
                res2[i][j] = res2[i - 1][j];
                for (int h = 1; h < j; ++h) {
                    res[i][j] = (res[i][j] + (res[i - h - 1][j - h] * dp[h]) % Mod * C[h][j]) % Mod;
                    res2[i][j] = (res2[i][j] + (res2[i - h - 1][j - h] * dp[h]) % Mod * C[h][j]) % Mod;
                    res2[i][j] = (res2[i][j] + (res[i - h - 1][j - h] * dp2[h]) % Mod * C[h][j]) % Mod;
                }
                res[i][j] = (res[i][j] + dp[j]) % Mod;
                res2[i][j] = (res2[i][j] + dp2[j]) % Mod;
            }
        }

        System.out.println(res2[n][m]);
        sc.close();
    }
}

